// Extract the binary PDF data and convert to base64 text.
// n8n stores downloaded files in $binary.data
const items = $input.all();
const results = [];

for (const item of items) {
  // Get the original filename from the trigger
  const fileName = item.json.name || 'rfp_document.pdf';

  // The binary data from Google Drive download
  const binaryData = item.binary?.data;

  if (!binaryData) {
    throw new Error('No binary data found in downloaded file');
  }

  results.push({
    json: {
      fileName,
      fileId: item.json.id,
      mimeType: binaryData.mimeType || 'application/pdf',
      fileSize: binaryData.fileSize,
      // Pass binary reference forward
    },
    binary: item.binary,
  });
}

return results;

// Clean up the raw extracted text before sending to Sellora backend.
// Removes excessive whitespace, page headers/footers noise, etc.
const items = $input.all();
const results = [];

for (const item of items) {
  let rawText = item.json.text || item.json.data || '';

  if (!rawText || rawText.trim().length < 50) {
    throw new Error(`PDF text extraction yielded too little content for file: ${item.json.fileName || 'unknown'}. The PDF may be scanned/image-based.`);
  }

  // Basic cleanup
  let cleanedText = rawText
    // Normalize line endings
    .replace(/\r\n/g, '\n')
    // Collapse 3+ blank lines into 2
    .replace(/\n{3,}/g, '\n\n')
    // Remove common PDF artifacts
    .replace(/\f/g, '\n')
    .trim();

  results.push({
    json: {
      fileName: item.json.fileName,
      fileId: item.json.fileId,
      rfpText: cleanedText,
      charCount: cleanedText.length,
      estimatedPages: Math.ceil(cleanedText.length / 3000),
    }
  });
}

return results;

const items = $input.all();
return items.map(item => {
  const data = item.json.data;
  if (item.json.success !== true || data?.version !== 1 || !Array.isArray(data.results) || data.results.length === 0) {
    throw new Error('Unexpected Sellora RFP response contract');
  }
  const rows = data.results.map((row, index) => {
    if (row.index !== index || typeof row.rowId !== 'string' || typeof row.question !== 'string' || !['success', 'refusal', 'error'].includes(row.status)) {
      throw new Error('Invalid Sellora RFP row contract');
    }
    return {
      rowId: row.rowId,
      rowNumber: index + 1,
      originalQuestion: row.question,
      status: row.status,
      answer: row.status === 'success' ? row.answer : '',
      confidence: row.status === 'success' ? row.confidence : '',
      requiresReview: 'YES',
      errorCode: row.errorCode || '',
      topCitationSection: row.citations?.[0]?.sectionTitle || '',
      citationCount: row.citations?.length || 0,
    };
  });
  return { json: {
    rows,
    summary: {
      totalQuestions: rows.length,
      answeredCount: rows.filter(row => row.status === 'success').length,
      refusedCount: rows.filter(row => row.status === 'refusal').length,
      errorCount: rows.filter(row => row.status === 'error').length,
      aiInteractionId: data.extractionAiInteractionId || '',
    },
    sourceFileName: $('Clean & Validate Text').first().json.fileName,
    fileId: $('Clean & Validate Text').first().json.fileId,
  } };
});

const item = $input.first().json;
const headers = ['#', 'Row ID', 'Original Question', 'Status', 'Answer', 'Confidence', 'Requires Manual Review?', 'Error Code', 'Source Section', 'Citations Used'];
const dataRows = item.rows.map(row => [row.rowNumber, row.rowId, row.originalQuestion, row.status, row.answer, row.confidence, row.requiresReview, row.errorCode, row.topCitationSection, row.citationCount]);
return [{ json: {
  headers,
  dataRows,
  allRows: [headers, ...dataRows],
  sourceFileName: item.sourceFileName,
  summary: item.summary,
} }];
